package ma.ilyas;
import org.junit.jupiter.api.Test;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.beans.factory.annotation.Autowired;import org.axonframework.commandhandling.gateway.CommandGateway;import org.axonframework.queryhandling.QueryGateway;import java.math.BigDecimal;import static ma.ilyas.Messages.*;import static org.junit.jupiter.api.Assertions.*;
@org.springframework.test.context.TestExecutionListeners(listeners=org.springframework.test.context.support.DependencyInjectionTestExecutionListener.class,mergeMode=org.springframework.test.context.TestExecutionListeners.MergeMode.REPLACE_DEFAULTS) @SpringBootTest class ProjectionIntegrationTest {
@Autowired CommandGateway commands;@Autowired QueryGateway queries;
@Test void roundTrip() throws Exception {String id=java.util.UUID.randomUUID().toString();commands.sendAndWait(new Create(id,new BigDecimal("100")));commands.sendAndWait(new Activate(id));commands.sendAndWait(new Credit(id,new BigDecimal("25")));commands.sendAndWait(new Debit(id,new BigDecimal("10")));StatementView s=queries.query(new Statement(id),StatementView.class).get(10,java.util.concurrent.TimeUnit.SECONDS);assertEquals(0,s.account().balance().compareTo(new BigDecimal("115")));assertEquals(2,s.operations().size());}}
